def choose_move(observation):
    def clamp(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def xy(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return (v[0], v[1])
        if isinstance(v, dict):
            if "x" in v and "y" in v:
                return (v.get("x"), v.get("y"))
        return None

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(a, b):
        return [clamp(b[0] - a[0]), clamp(b[1] - a[1])]

    def step_away(a, b):
        return [clamp(a[0] - b[0]), clamp(a[1] - b[1])]

    def best_point(items, src, farthest=False):
        best = None
        best_d = None
        for it in items or []:
            p = xy(it)
            if p is None:
                continue
            d = manhattan(src, p)
            if best is None or (d > best_d if farthest else d < best_d):
                best = p
                best_d = d
        return best

    def normalize_move(m):
        return [clamp(m[0]), clamp(m[1])]

    env = observation.get("environment_name", "")
    role = observation.get("self_role", "")
    self_pos = xy(observation.get("self_position")) or xy(observation.get("agent_position")) or (0, 0)
    opp_pos = xy(observation.get("opponent_position")) or xy(observation.get("enemy_position")) or self_pos
    w = observation.get("grid_width", observation.get("width", 0)) or 0
    h = observation.get("grid_height", observation.get("height", 0)) or 0

    if env == "pursuit_evasion":
        if role == "evader":
            corners = []
            if w and h:
                corners = [(0, 0), (0, h - 1), (w - 1, 0), (w - 1, h - 1)]
            target = best_point(corners, opp_pos, farthest=True)
            if target is not None:
                return normalize_move(step_toward(self_pos, target))
            return normalize_move(step_away(self_pos, opp_pos))
        return normalize_move(step_toward(self_pos, opp_pos))

    if env == "territory_control":
        targets = (
            observation.get("unclaimed_cells")
            or observation.get("neutral_cells")
            or observation.get("opponent_territory")
            or observation.get("frontier")
            or observation.get("targets")
            or []
        )
        target = best_point(targets, self_pos)
        if target is None and w and h:
            target = (w // 2, h // 2)
        if target is not None:
            return normalize_move(step_toward(self_pos, target))
        return normalize_move(step_away(self_pos, opp_pos))

    resources = (
        observation.get("resources")
        or observation.get("resource_cells")
        or observation.get("resource_positions")
        or observation.get("food")
        or []
    )
    target = best_point(resources, self_pos)
    if target is not None:
        opp_target = best_point(resources, opp_pos)
        if opp_target is not None and manhattan(self_pos, target) > manhattan(opp_pos, target):
            return normalize_move(step_away(self_pos, opp_pos))
        return normalize_move(step_toward(self_pos, target))

